<?php require 'config.php';if(!user()){header('Location: login.php');exit;} $u=user();if(isset($_POST['profile'])){$st=$conn->prepare("UPDATE users SET name=?,email=?,phone=? WHERE id=?");$st->bind_param("sssi",$_POST['name'],$_POST['email'],$_POST['phone'],$u['id']);$st->execute();$u=$conn->query("SELECT * FROM users WHERE id=".$u['id'])->fetch_assoc();$_SESSION['user']=$u;}if(isset($_GET['cancel'])){$id=(int)$_GET['cancel'];$st=$conn->prepare("SELECT * FROM bookings WHERE id=? AND user_id=?");$st->bind_param("ii",$id,$u['id']);$st->execute();$b=$st->get_result()->fetch_assoc();if($b&&floor((strtotime($b['check_in'])-time())/86400)>=3)$conn->query("UPDATE bookings SET status='Cancelled' WHERE id=$id");} $st=$conn->prepare("SELECT b.*,r.type FROM bookings b JOIN rooms r ON r.id=b.room_id WHERE b.user_id=? ORDER BY b.id DESC");$st->bind_param("i",$u['id']);$st->execute();$bs=$st->get_result();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard</title><link rel="stylesheet" href="assets/style.css"></head><body><header><div class="logo">StayEase</div><nav><a href="index.php">Home</a><a href="logout.php">Logout</a></nav></header><main class="section"><h1>My Dashboard</h1><div class="dash"><div class="panel"><h2>Profile</h2><form method="post"><input name="name" value="<?=e($u['name'])?>" required><input name="email" type="email" value="<?=e($u['email'])?>" required><input name="phone" value="<?=e($u['phone'])?>"><button class="btn" name="profile">Save Profile</button></form></div><div class="panel"><h2>Booking History</h2><?php if(isset($_GET['booked'])):?><p class="success">Booking confirmed successfully.</p><?php endif;?><?php while($b=$bs->fetch_assoc()):?><div class="booking"><b><?=e($b['type'])?></b> <span class="status"><?=e($b['status'])?></span><p>Booking #<?=$b['id']?> | <?=$b['check_in']?> → <?=$b['check_out']?> | ₹<?=number_format($b['total'])?></p><?php if($b['status']=='Confirmed'&&floor((strtotime($b['check_in'])-time())/86400)>=3):?><a class="btn small danger" href="?cancel=<?=$b['id']?>" onclick="return confirm('Cancel booking?')">Cancel</a><?php endif;?></div><?php endwhile;?></div></div></main></body></html>